pub fn havoc_inline_post(v: &mut Vec<u32>, a: u32, b: bool) {
    // Assumptions from the problem statement:
    // - v may be empty
    // - all elements of v are initially 1
    // - 10 < a < 20
    // - b == false

    // Modify in place: each element becomes 1 + a.
    // This is safe in u32 because a < 20, so 1 + a <= 20.
    for x in v.iter_mut() {
        *x = x.wrapping_add(a);
    }

    // Optional debug-time checks reflecting the required postconditions.
    debug_assert!(a > 10 && a < 20);
    debug_assert!(2 * a > 20 && 2 * a < 40);
    debug_assert!(!b);

    for &x in v.iter() {
        debug_assert!(x == 1 + a);
    }
}